/**
 * Checking every followed swap together (SWAP_WATCH_BUNDLE=true): an old swap, normally checked only every SWAP_WATCH_LONG_INTERVAL_MINUTES, comes along in the requests for a newer one — without any extra request.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L19  Helpers
// L26    follow()
// L33  Followed swaps are checked together
// ----- end of contents -----

import test, { afterEach } from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, stubMeson, makeWorld, swapId, sleep, texts, MOVING, DONE } from './helpers.mjs'

useFakeSettings({ SWAP_WATCH_BUNDLE: 'true' })
const { watchSwap, stopWatchingChannel } = await import('../src/watch.js')
const { getSwaps } = await import('../src/meson.js')
const { getTicket } = await import('../src/ticket-state.js')

// =============================================================================
//   Helpers
// =============================================================================

afterEach(() => { for (let i = 1; i <= 9; i++) stopWatchingChannel(`b${i}`) })

/** Start following one swap in `world`'s ticket. */
async function follow (world, id, n = 1) {
  const t = getTicket(world.channel.id)
  const entry = { n, swapId: id, message: world.message(n, world.me), latest: (await getSwaps([id])).get(id) }
  t.swaps.push(entry)
  await watchSwap(t, entry)
}

// =============================================================================
//   Followed swaps are checked together
// =============================================================================

test('an old swap that finishes is posted with the next check of a newer swap, not at its own long interval', async () => {
  const old = swapId('a')
  const fresh = swapId('b')
  const events = { [old]: MOVING, [fresh]: MOVING }
  stubMeson({ events, old: [old] })
  const first = makeWorld('b1')
  const second = makeWorld('b2')
  await follow(first, old)
  await sleep(1500) // its first check: the next one is due only after the long interval
  await follow(second, fresh)
  events[old] = DONE
  await sleep(2500)
  assert.equal(texts(first.posted).filter((x) => x.includes('Transaction Completed')).length, 1)
})

test('bundling never adds a request: other swaps only fill the spare places of a request that is sent anyway', async () => {
  const olds = Array.from({ length: 25 }, (_, i) => '0x' + (i + 1).toString(16).padStart(64, '0'))
  const fresh = swapId('c')
  const count = stubMeson({ old: olds })
  const many = makeWorld('b3')
  for (const [i, id] of olds.entries()) await follow(many, id, i + 1)
  await follow(makeWorld('b4'), fresh)
  await sleep(1500) // the first checks of all 26
  count.requests = 0
  await sleep(3200) // three rounds, in each only the fresh swap is due
  assert.ok(count.requests <= 4, `${count.requests} requests in three rounds — one per round expected, not two`)
})
